parameters.item/cr174_wait_time:
@if(
  equals(first(outputs('List_rows_Audits')?['body/value'])?['cr174_inexam'], true),
  0,
  if(
    not(empty(first(outputs('List_rows_Audits')?['body/value'])?['cr174_last_examline_endtime'])),
    div(
      sub(
        ticks(utcNow()),
        ticks(first(outputs('List_rows_Audits')?['body/value'])?['cr174_last_examline_endtime'])
      ),
      600000000
    ),
    if(
      and(
        not(empty(first(outputs('List_rows_Audits')?['body/value'])?['cr174_checkintime'])),
        not(empty(first(outputs('List_rows_Audits')?['body/value'])?['cr174_appointmentstatuslabel'])),
        equals(first(outputs('List_rows_Audits')?['body/value'])?['cr174_appointmentstatuslabel'], 'Checked In')
      ),
      div(
        sub(
          ticks(utcNow()),
          ticks(first(outputs('List_rows_Audits')?['body/value'])?['cr174_checkintime'])
        ),
        600000000
      ),
      0
    )
  )
)

parameters.item/cr174_finanlcellcontent:
@concat(
  first(outputs('List_rows_exam_line_By_Apptid')?['body/value'])?['cr174_service_columnkey'],
  decodeUriComponent('%0A'),
  if(
    empty(first(outputs('List_rows_exam_line_By_Apptid')?['body/value'])?['cr174_resource_examline']),
    first(outputs('List_rows_exam_line_By_Apptid')?['body/value'])?['cr174_modify_nm_examline'],
    first(outputs('List_rows_exam_line_By_Apptid')?['body/value'])?['cr174_resourcenm_examline']
  ),
  decodeUriComponent('%0A'),
  if(
    empty(first(outputs('List_rows_exam_line_By_Apptid')?['body/value'])?['cr174_line_starttime']),
    '',
    formatDateTime(
          first(outputs('List_rows_exam_line_By_Apptid')?['body/value'])?['cr174_line_starttime'],
   
      'hh:mm tt'
    )
  ),
  decodeUriComponent('%0A'),
  decodeUriComponent('%0A'),
  if(
    empty(first(outputs('List_rows_exam_line_By_Apptid')?['body/value'])?['cr174_first_examline_starttime']),
    '0 mins',
    concat(
      string(
        div(
          sub(
             ticks(convertFromUtc(
                    utcNow(),
                    first(outputs('List_rows_time_zone')?['body/value'])?['standardname']
                     )),
            ticks(first(outputs('List_rows_exam_line_By_Apptid')?['body/value'])?['cr174_first_examline_starttime'])
          ),
          600000000
        )
      ),
      ' mins'
    )
  )
)

